SELECT

FROM tms_trade_blotter


        AND remark = #{condition.remark}


        AND buy_sell_borrow_lend = #{condition.buySellBorrowLend}


        AND trade_number LIKE CONCAT('%', #{condition.tradeNumber}, '%')


        AND trade_date >= #{condition.tradeDateStart}


        AND trade_date <= #{condition.tradeDateEnd}


        AND value_date >= #{condition.valueDateStart}


        AND value_date <= #{condition.valueDateEnd}


        AND maturity_date >= #{condition.maturityDateStart}


        AND maturity_date <= #{condition.maturityDateEnd}


        AND currency = #{condition.currency}


        AND settlement_amount >= #{condition.settlementAmountMin}


        AND settlement_amount <= #{condition.settlementAmountMax}


        AND isin = #{condition.isin}


        AND payment_status = #{condition.paymentStatus}


        AND journal_status = #{condition.journalStatus}


        AND journal_sequence LIKE CONCAT('%', #{condition.journalSequence}, '%')


ORDER BY trade_date DESC, trade_number DESC

SELECT COUNT(1)
FROM tms_trade_blotter


        AND remark = #{condition.remark}


        AND buy_sell_borrow_lend = #{condition.buySellBorrowLend}


        AND trade_number LIKE CONCAT('%', #{condition.tradeNumber}, '%')


        AND trade_date >= #{condition.tradeDateStart}


        AND trade_date <= #{condition.tradeDateEnd}


        AND value_date >= #{condition.valueDateStart}


        AND value_date <= #{condition.valueDateEnd}


        AND maturity_date >= #{condition.maturityDateStart}


        AND maturity_date <= #{condition.maturityDateEnd}


        AND currency = #{condition.currency}


        AND settlement_amount >= #{condition.settlementAmountMin}


        AND settlement_amount <= #{condition.settlementAmountMax}


        AND isin = #{condition.isin}


        AND payment_status = #{condition.paymentStatus}


        AND journal_status = #{condition.journalStatus}


        AND journal_sequence LIKE CONCAT('%', #{condition.journalSequence}, '%')
